// TypeScript Version: 4.1

/* eslint-disable max-lines */

import cdf = require( '@stdlib/stats/base/dists/wald/cdf' );
import Wald = require( '@stdlib/stats/base/dists/wald/ctor' );
import kurtosis = require( '@stdlib/stats/base/dists/wald/kurtosis' );
import logcdf = require( '@stdlib/stats/base/dists/wald/logcdf' );
import logpdf = require( '@stdlib/stats/base/dists/wald/logpdf' );
import mean = require( '@stdlib/stats/base/dists/wald/mean' );
import mgf = require( '@stdlib/stats/base/dists/wald/mgf' );
import mode = require( '@stdlib/stats/base/dists/wald/mode' );
import pdf = require( '@stdlib/stats/base/dists/wald/pdf' );
import quantile = require( '@stdlib/stats/base/dists/wald/quantile' );
import skewness = require( '@stdlib/stats/base/dists/wald/skewness' );
import stdev = require( '@stdlib/stats/base/dists/wald/stdev' );
import variance = require( '@stdlib/stats/base/dists/wald/variance' );

/**
* Interface describing the `wald` namespace.
*/
interface Namespace {
	/**
	* Wald distribution cumulative distribution function (CDF).
	*
	* @param x - input value
	* @param mu - mean
	* @param lambda - shape parameter
	* @returns evaluated CDF
	*
	* @example
	* var y = ns.cdf( 2.0, 1.0, 1.0 );
	* // returns ~0.885
	*
	* var myCDF = ns.cdf.factory( 4.0, 2.0 );
	* y = myCDF( 5.0 );
	* // returns ~0.773
	*/
	cdf: typeof cdf;

	/**
	* Wald distribution.
	*/
	Wald: typeof Wald;

	/**
	* Returns the excess kurtosis for a Wald distribution with mean `mu` and shape parameter `lambda`.
	*
	* ## Notes
	*
	* -   If provided `mu <= 0` or `lambda <= 0`, the function returns `NaN`.
	*
	* @param mu - mean
	* @param lambda - shape parameter
	* @returns excess kurtosis
	*
	* @example
	* var y = ns.kurtosis( 5.0, 2.0 );
	* // returns 37.5
	*
	* @example
	* var y = ns.kurtosis( NaN, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = ns.kurtosis( 0.0, NaN );
	* // returns NaN
	*
	* @example
	* var y = ns.kurtosis( 0.0, 0.0 );
	* // returns NaN
	*/
	kurtosis: typeof kurtosis;

	/**
	* Wald distribution natural logarithm of cumulative distribution function (CDF).
	*
	* @param x - input value
	* @param mu - mean
	* @param lambda - shape parameter
	* @returns evaluated logCDF
	*
	* @example
	* var y = ns.logcdf( 2.0, 1.0, 1.0 );
	* // returns ~-0.122
	*
	* var mylogcdf = ns.logcdf.factory( 4.0, 2.0 );
	* y = mylogcdf( 5.0 );
	* // returns ~-0.257
	*/
	logcdf: typeof logcdf;

	/**
	* Wald distribution natural logarithm of probability density function (logPDF).
	*
	* @param x - input value
	* @param mu - mean
	* @param lambda - shape parameter
	* @returns evaluated logPDF
	*
	* @example
	* var y = ns.logpdf( 2.0, 1.0, 1.0 );
	* // returns ~-2.209
	*
	* var mylogpdf = ns.logpdf.factory( 4.0, 2.0 );
	* y = mylogpdf( 5.0 );
	* // returns ~-3.0
	*/
	logpdf: typeof logpdf;

	/**
	* Returns the expected value for a Wald distribution with mean `mu` and shape parameter `lambda`.
	*
	* ## Notes
	*
	* -   If provided `mu <= 0` or `lambda <= 0`, the function returns `NaN`.
	*
	* @param mu - mean
	* @param lambda - shape parameter
	* @returns expected value
	*
	* @example
	* var y = ns.mean( 5.0, 2.0 );
	* // returns 5.0
	*
	* @example
	* var y = ns.mean( NaN, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = ns.mean( 0.0, NaN );
	* // returns NaN
	*
	* @example
	* var y = ns.mean( 0.0, 0.0 );
	* // returns NaN
	*/
	mean: typeof mean;

	/**
	* Wald distribution moment-generating function (MGF).
	*
	* @param t - input value
	* @param mu - mean
	* @param lambda - shape parameter
	* @returns evaluated MGF
	*
	* @example
	* var y = ns.mgf( 0.1, 2.0, 3.0 );
	* // returns ~1.2405
	*
	* var mymgf = ns.mgf.factory( 4.0, 2.0 );
	* y = mymgf( 0.05 );
	* // returns ~1.318
	*/
	mgf: typeof mgf;

	/**
	* Returns the mode for a Wald distribution with mean `mu` and shape parameter `lambda`.
	*
	* ## Notes
	*
	* -   If provided `mu <= 0` or `lambda <= 0`, the function returns `NaN`.
	*
	* @param mu - mean
	* @param lambda - shape parameter
	* @returns mode
	*
	* @example
	* var y = ns.mode( 5.0, 2.0 );
	* // returns ~0.655
	*
	* @example
	* var y = ns.mode( NaN, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = ns.mode( 1.0, NaN );
	* // returns NaN
	*
	* @example
	* var y = ns.mode( 0.0, 1.0 );
	* // returns NaN
	*/
	mode: typeof mode;

	/**
	* Wald distribution probability density function (PDF).
	*
	* @param x - input value
	* @param mu - mean
	* @param lambda - shape parameter
	* @returns evaluated PDF
	*
	* @example
	* var y = ns.pdf( 2.0, 1.0, 1.0 );
	* // returns ~0.110
	*
	* var myPDF = ns.pdf.factory( 4.0, 2.0 );
	* y = myPDF( 5.0 );
	* // returns ~0.0498
	*/
	pdf: typeof pdf;

	/**
	* Wald distribution quantile function.
	*
	* @param p - input value
	* @param mu - mean
	* @param lambda - shape parameter
	* @returns evaluated quantile function
	*
	* @example
	* var y = ns.quantile( 0.8, 1.0, 1.0 );
	* // returns ~1.448
	*
	* var myQuantile = ns.quantile.factory( 4.0, 2.0 );
	* y = myQuantile( 0.5 );
	* // returns ~2.057
	*/
	quantile: typeof quantile;

	/**
	* Returns the skewness for a Wald distribution with mean `mu` and shape parameter `lambda`.
	*
	* ## Notes
	*
	* -   If provided `mu <= 0` or `lambda <= 0`, the function returns `NaN`.
	*
	* @param mu - mean
	* @param lambda - shape parameter
	* @returns skewness
	*
	* @example
	* var y = ns.skewness( 5.0, 2.0 );
	* // returns ~4.743
	*
	* @example
	* var y = ns.skewness( NaN, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = ns.skewness( 1.0, NaN );
	* // returns NaN
	*
	* @example
	* var y = ns.skewness( 0.0, 0.0 );
	* // returns NaN
	*/
	skewness: typeof skewness;

	/**
	* Returns the standard deviation for a Wald distribution with mean `mu` and shape parameter `lambda`.
	*
	* ## Notes
	*
	* -   If provided `mu <= 0` or `lambda <= 0`, the function returns `NaN`.
	*
	* @param mu - mean
	* @param lambda - shape parameter
	* @returns standard deviation
	*
	* @example
	* var y = ns.stdev( 2.0, 1.0 );
	* // returns ~2.828
	*
	* @example
	* var y = ns.stdev( NaN, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = ns.stdev( 0.0, NaN );
	* // returns NaN
	*
	* @example
	* var y = ns.stdev( 1.0, 0.0 );
	* // returns NaN
	*/
	stdev: typeof stdev;

	/**
	* Returns the variance for a Wald distribution with mean `mu` and shape parameter `lambda`.
	*
	* ## Notes
	*
	* -   If provided `mu <= 0` or `lambda <= 0`, the function returns `NaN`.
	*
	* @param mu - mean
	* @param lambda - shape parameter
	* @returns variance
	*
	* @example
	* var y = ns.variance( 5.0, 3.0 );
	* // returns ~41.67
	*
	* @example
	* var y = ns.variance( NaN, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = ns.variance( 0.0, NaN );
	* // returns NaN
	*
	* @example
	* var y = ns.variance( 1.0, 0.0 );
	* // returns NaN
	*/
	variance: typeof variance;
}

/**
* Wald distribution.
*/
declare var ns: Namespace;


// EXPORTS //

export = ns;
